$page_title='คลังสินค้า';require_once __DIR__.'/includes/auth_check.php';requireSeller();require_once __DIR__.'/config/database.php';$db=(new Database())->getConnection();$sellerId=(int)$_SESSION['user_id'];$message=$error='';
$profile=$db->prepare("SELECT store_status,product_submission_enabled FROM seller_profiles WHERE user_id=? AND status='approved'");$profile->execute([$sellerId]);$profile=$profile->fetch();if(!$profile){header('Location: '.BASE_URL.'seller.php');exit;}
if(($_GET['export']??'')==='csv'){$q=$db->prepare("SELECT p.id,p.name,COALESCE(v.sku,CONCAT('PRODUCT-',p.id)) sku,COALESCE(v.name,'สินค้าหลัก') option_name,COALESCE(v.stock_quantity,p.stock_quantity) stock,p.approval_status FROM products p LEFT JOIN product_variants v ON v.product_id=p.id WHERE p.seller_id=? ORDER BY p.id,v.id");$q->execute([$sellerId]);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="inventory-'.date('Ymd').'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');fputcsv($out,['product_id','name','sku','option','stock','status']);foreach($q as $row)fputcsv($out,$row);fclose($out);exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf(false);try{if($profile['store_status']!=='active'||!(int)$profile['product_submission_enabled'])throw new RuntimeException('ร้านถูกจำกัดการจัดการคลังสินค้า');$productId=(int)($_POST['product_id']??0);$variantId=(int)($_POST['variant_id']??0)?:null;$change=(int)($_POST['quantity_change']??0);$note=trim((string)($_POST['note']??''));if($change===0||abs($change)>100000)throw new RuntimeException('จำนวนที่ปรับไม่ถูกต้อง');$db->beginTransaction();if($variantId){$q=$db->prepare('SELECT v.stock_quantity FROM product_variants v JOIN products p ON p.id=v.product_id WHERE v.id=? AND p.id=? AND p.seller_id=? FOR UPDATE');$q->execute([$variantId,$productId,$sellerId]);$before=$q->fetchColumn();if($before===false)throw new RuntimeException('ไม่พบ SKU');$after=(int)$before+$change;if($after<0)throw new RuntimeException('สต็อกคงเหลือติดลบไม่ได้');$db->prepare('UPDATE product_variants SET stock_quantity=? WHERE id=?')->execute([$after,$variantId]);$db->prepare('UPDATE products SET stock_quantity=(SELECT COALESCE(SUM(stock_quantity),0) FROM product_variants WHERE product_id=?) WHERE id=?')->execute([$productId,$productId]);}else{$q=$db->prepare('SELECT stock_quantity FROM products WHERE id=? AND seller_id=? FOR UPDATE');$q->execute([$productId,$sellerId]);$before=$q->fetchColumn();if($before===false)throw new RuntimeException('ไม่พบสินค้า');$after=(int)$before+$change;if($after<0)throw new RuntimeException('สต็อกคงเหลือติดลบไม่ได้');$db->prepare('UPDATE products SET stock_quantity=? WHERE id=?')->execute([$after,$productId]);}$type=$change>0?'manual_add':'manual_remove';$db->prepare('INSERT INTO inventory_movements(seller_id,product_id,variant_id,movement_type,quantity_change,quantity_before,quantity_after,note,created_by) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$sellerId,$productId,$variantId,$type,$change,$before,$after,$note?:null,$sellerId]);auditLog($db,'seller.inventory.adjust','product',$productId,null,['variant_id'=>$variantId,'change'=>$change,'before'=>$before,'after'=>$after]);$db->commit();$message='ปรับสต็อกเรียบร้อยแล้ว';}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}}
$search=trim((string)($_GET['q']??''));$stock=(string)($_GET['stock']??'all');$params=[$sellerId];$where='p.seller_id=?';if($search!==''){$where.=' AND (p.name LIKE ? OR v.sku LIKE ?)';$params[]='%'.$search.'%';$params[]='%'.$search.'%';}if($stock==='low')$where.=' AND COALESCE(v.stock_quantity,p.stock_quantity)<=5';elseif($stock==='out')$where.=' AND COALESCE(v.stock_quantity,p.stock_quantity)=0';$q=$db->prepare("SELECT p.id,p.name,p.approval_status,v.id variant_id,v.sku,v.name variant_name,COALESCE(v.stock_quantity,p.stock_quantity) stock FROM products p LEFT JOIN product_variants v ON v.product_id=p.id WHERE $where ORDER BY COALESCE(v.stock_quantity,p.stock_quantity),p.name");$q->execute($params);$items=$q->fetchAll();$summary=$db->prepare("SELECT COUNT(*) products,SUM(stock_quantity=0) out_stock,SUM(stock_quantity BETWEEN 1 AND 5) low_stock,COALESCE(SUM(stock_quantity),0) units FROM products WHERE seller_id=?");$summary->execute([$sellerId]);$summary=$summary->fetch();$history=$db->prepare('SELECT im.*,p.name product_name,v.sku FROM inventory_movements im JOIN products p ON p.id=im.product_id LEFT JOIN product_variants v ON v.id=im.variant_id WHERE im.seller_id=? ORDER BY im.id DESC LIMIT 30');$history->execute([$sellerId]);$history=$history->fetchAll();require_once __DIR__.'/includes/header.php';?>
<link rel="stylesheet" href="<?php echo BASE_URL;?>assets/css/seller.css"><main id="main-content" class="seller-page"><div class="container"><?php require __DIR__.'/includes/seller_nav.php';?><header class="store-section-header"><div><p class="eyebrow">INVENTORY CONTROL</p><h1>คลังสินค้า</h1><p>ค้นหา SKU ปรับยอด และตรวจสอบประวัติทุกการเปลี่ยนแปลง</p></div><a class="btn btn-outline" href="?export=csv"><i class="fa-solid fa-file-csv"></i> ส่งออก CSV</a></header><?php if($message):?><p class="seller-success" role="status"><?php echo e($message);?></p><?php endif;?><?php if($error):?><p class="seller-error" role="alert"><?php echo e($error);?></p><?php endif;?>
<section class="seller-ops-grid"><div class="seller-ops-card"><small>สินค้าทั้งหมด</small><strong><?php echo (int)$summary['products'];?></strong></div><div class="seller-ops-card"><small>จำนวนรวมในคลัง</small><strong><?php echo (int)$summary['units'];?></strong></div><div class="seller-ops-card"><small>ใกล้หมด ≤ 5</small><strong><?php echo (int)$summary['low_stock'];?></strong></div><div class="seller-ops-card"><small>สินค้าหมด</small><strong><?php echo (int)$summary['out_stock'];?></strong></div></section>
<div class="seller-toolbar"><form method="get"><input name="q" value="<?php echo e($search);?>" placeholder="ค้นหาชื่อสินค้า หรือ SKU"><select name="stock"><option value="all">ทุกระดับสต็อก</option><option value="low" <?php echo $stock==='low'?'selected':'';?>>ใกล้หมด</option><option value="out" <?php echo $stock==='out'?'selected':'';?>>หมด</option></select><button class="btn btn-primary">ค้นหา</button></form></div><section class="admin-panel"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>สินค้า / SKU</th><th>สถานะ</th><th>คงเหลือ</th><th>ปรับสต็อก</th></tr></thead><tbody><?php if(!$items):?><tr><td colspan="4" class="admin-empty">ไม่พบสินค้า</td></tr><?php endif;?><?php foreach($items as $x):?><tr><td><strong><?php echo e($x['name']);?></strong><span class="cell-subtitle"><?php echo e($x['sku']?:'PRODUCT-'.$x['id']);?><?php echo $x['variant_name']?' · '.e($x['variant_name']):'';?></span></td><td><span class="status-badge <?php echo $x['approval_status']==='approved'?'paid':'pending';?>"><?php echo e($x['approval_status']);?></span></td><td class="<?php echo (int)$x['stock']<=5?'stock-low':'stock-ok';?>"><?php echo (int)$x['stock'];?> ชิ้น</td><td><form method="post" class="inventory-adjust"><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken());?>"><input type="hidden" name="product_id" value="<?php echo (int)$x['id'];?>"><input type="hidden" name="variant_id" value="<?php echo (int)$x['variant_id'];?>"><input type="number" name="quantity_change" placeholder="+/-" required><input name="note" placeholder="เหตุผล" maxlength="255"><button class="btn btn-primary">บันทึก</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="admin-panel seller-product-list"><header class="admin-panel-header"><div><h2>ประวัติการเคลื่อนไหวล่าสุด</h2><p>ตรวจสอบย้อนหลังว่าใครปรับอะไร เมื่อใด</p></div></header><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>เวลา</th><th>สินค้า</th><th>เปลี่ยนแปลง</th><th>ก่อน → หลัง</th><th>เหตุผล</th></tr></thead><tbody><?php if(!$history):?><tr><td colspan="5" class="admin-empty">ยังไม่มีประวัติ</td></tr><?php endif;?><?php foreach($history as $h):?><tr><td><?php echo date('d/m/Y H:i',strtotime($h['created_at']));?></td><td><?php echo e($h['product_name']);?><span class="cell-subtitle"><?php echo e($h['sku']??'สินค้าหลัก');?></span></td><td class="<?php echo (int)$h['quantity_change']<0?'stock-low':'stock-ok';?>"><?php echo (int)$h['quantity_change']>0?'+':'';?><?php echo (int)$h['quantity_change'];?></td><td><?php echo (int)$h['quantity_before'];?> → <?php echo (int)$h['quantity_after'];?></td><td><?php echo e($h['note']?:'-');?></td></tr><?php endforeach;?></tbody></table></div></section></div></main><?php require_once __DIR__.'/includes/footer.php';?>
